#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <sstream>
#include <string>
#include <vector>

struct Score { int points; std::string name; };
struct SaveData
{
    int level{ 1 };
    int coins{ 0 };
    std::vector<std::string> unlocked;
    std::vector<Score> scores;
};
enum class LoadResult { Ok, Missing, Damaged, TooNew };

std::uint32_t fnv1a(const std::string& text)
{
    std::uint32_t h{ 2166136261u };
    for (unsigned char c : text) { h ^= c; h *= 16777619u; }
    return h;
}

namespace
{
    std::string hex8(std::uint32_t v)
    {
        char buffer[9];
        std::snprintf(buffer, sizeof(buffer), "%08x", static_cast<unsigned>(v));
        return buffer;
    }

    bool readInt(const std::string& s, int& out)
    {
        if (s.empty()) return false;
        std::size_t used{ 0 };
        try { out = std::stoi(s, &used); } catch (...) { return false; }
        return used == s.size();
    }
}

std::string writeSave(const SaveData& s)
{
    std::string body{ "xenon-save 2\nlevel " + std::to_string(s.level) + "\ncoins " + std::to_string(s.coins) + "\nunlocked " };
    for (std::size_t i{ 0 }; i < s.unlocked.size(); ++i) body += (i ? "," : "") + s.unlocked[i];
    body += "\n";
    for (const Score& sc : s.scores) body += "score " + std::to_string(sc.points) + " " + sc.name + "\n";
    return body + "checksum " + hex8(fnv1a(body)) + "\n";
}

LoadResult loadSave(const std::string& text, SaveData& out)
{
    if (text.empty()) return LoadResult::Missing;

    // Split into lines, remembering where each starts, so the checksum covers the stored bytes.
    std::vector<std::string> lines;
    std::vector<std::size_t> starts;
    std::size_t pos{ 0 };
    while (pos < text.size())
    {
        std::size_t end{ text.find('\n', pos) };
        if (end == std::string::npos) end = text.size();
        std::string line{ text.substr(pos, end - pos) };
        if (!line.empty() && line.back() == '\r') line.pop_back();
        starts.push_back(pos);
        lines.push_back(line);
        pos = end + 1;
    }

    int version{ 0 };
    if (lines[0].rfind("xenon-save ", 0) != 0 || !readInt(lines[0].substr(11), version)) return LoadResult::Damaged;
    if (version > 2) return LoadResult::TooNew;
    if (version < 1) return LoadResult::Damaged;

    const std::string& last{ lines.back() };
    if (lines.size() < 2 || last.rfind("checksum ", 0) != 0) return LoadResult::Damaged;
    if (last.substr(9) != hex8(fnv1a(text.substr(0, starts.back())))) return LoadResult::Damaged;

    SaveData s;
    for (std::size_t i{ 1 }; i + 1 < lines.size(); ++i)
    {
        const std::string& l{ lines[i] };
        const auto space{ l.find(' ') };
        const std::string key{ l.substr(0, space) };
        const std::string value{ space == std::string::npos ? "" : l.substr(space + 1) };
        int n{ 0 };
        if (key == "level") { if (!readInt(value, n) || n < 1) return LoadResult::Damaged; s.level = n; }
        else if ((key == "coins" && version == 2) || (key == "gold" && version == 1)) { if (!readInt(value, n) || n < 0) return LoadResult::Damaged; s.coins = n; }
        else if (key == "unlocked" && version == 2)
        {
            std::istringstream parts{ value };
            for (std::string a; std::getline(parts, a, ',');) if (!a.empty()) s.unlocked.push_back(a);
        }
        else if (key == "score")
        {
            const auto sp{ value.find(' ') };
            if (sp == std::string::npos || !readInt(value.substr(0, sp), n)) return LoadResult::Damaged;
            s.scores.push_back({ n, value.substr(sp + 1) });
        }
    }
    out = std::move(s);
    return LoadResult::Ok;
}

int chooseSave(const std::string& primary, const std::string& backup, SaveData& out)
{
    if (loadSave(primary, out) == LoadResult::Ok) return 1;
    if (loadSave(backup, out) == LoadResult::Ok) return 2;
    out = SaveData{};
    return 0;
}

int addScore(std::vector<Score>& table, const std::string& name, int points)
{
    const auto it{ std::find_if(table.begin(), table.end(), [&](const Score& s) { return points > s.points; }) };
    const std::size_t rank{ static_cast<std::size_t>(it - table.begin()) };
    if (rank >= 5) return 0;
    table.insert(it, { points, name });
    if (table.size() > 5) table.resize(5);
    return static_cast<int>(rank) + 1;
}

unitTests:
std::string hexOf(std::uint32_t v) { char b[9]; std::snprintf(b, sizeof(b), "%08x", static_cast<unsigned>(v)); return b; }
std::string signedBody(const std::string& body) { return body + "checksum " + hexOf(fnv1a(body)) + "\n"; }
SaveData sample() { SaveData s; s.level = 3; s.coins = 120; s.unlocked = { "forest", "caves" }; s.scores = { { 1200, "Sam" }, { 900, "Alex Smith" } }; return s; }
TEST("the hash") { CHECK_EQ(fnv1a(""), 0x811c9dc5u); CHECK_EQ(fnv1a("a"), 0xe40c292cu); CHECK_EQ(fnv1a("foobar"), 0xbf9cf968u); }
TEST("writing") {
    const std::string body = "xenon-save 2\nlevel 3\ncoins 120\nunlocked forest,caves\nscore 1200 Sam\nscore 900 Alex Smith\n";
    CHECK_EQ(writeSave(sample()), signedBody(body));
    CHECK_EQ(writeSave(SaveData{}), signedBody("xenon-save 2\nlevel 1\ncoins 0\nunlocked \n"));
}
TEST("round trip") {
    SaveData back; CHECK(loadSave(writeSave(sample()), back) == LoadResult::Ok);
    CHECK_EQ(back.level, 3); CHECK_EQ(back.coins, 120); CHECK_EQ(back.unlocked, (std::vector<std::string>{ "forest", "caves" }));
    CHECK_EQ(back.scores.size(), std::size_t{ 2 }); CHECK_EQ(back.scores[1].name, std::string("Alex Smith")); CHECK_EQ(back.scores[1].points, 900);
    SaveData empty; CHECK(loadSave(writeSave(SaveData{}), empty) == LoadResult::Ok); CHECK(empty.unlocked.empty());
}
TEST("damage is detected") {
    std::string text = writeSave(sample()); SaveData out; out.level = 42;
    std::string edited = text; edited[text.find("120")] = '9'; CHECK(loadSave(edited, out) == LoadResult::Damaged);
    CHECK(loadSave(text.substr(0, text.size() / 2), out) == LoadResult::Damaged);
    CHECK(loadSave(signedBody("xenon-save 2\nlevel 0\n"), out) == LoadResult::Damaged);
    CHECK(loadSave("", out) == LoadResult::Missing); CHECK(loadSave(signedBody("xenon-save 3\nlevel 1\n"), out) == LoadResult::TooNew);
    CHECK_EQ(out.level, 42);
}
TEST("windows line endings and unknown lines") {
    SaveData out; CHECK(loadSave(signedBody("xenon-save 2\r\nlevel 5\r\nmood happy\r\n"), out) == LoadResult::Ok); CHECK_EQ(out.level, 5);
}
TEST("version 1 is migrated") {
    SaveData out; CHECK(loadSave(signedBody("xenon-save 1\nlevel 2\ngold 75\nscore 300 Kim\n"), out) == LoadResult::Ok);
    CHECK_EQ(out.coins, 75); CHECK_EQ(out.level, 2); CHECK(out.unlocked.empty()); CHECK_EQ(out.scores[0].name, std::string("Kim"));
}
TEST("the backup") {
    SaveData out; const std::string good = writeSave(sample());
    CHECK_EQ(chooseSave(good, "", out), 1); CHECK_EQ(chooseSave(good.substr(0, 20), good, out), 2); CHECK_EQ(out.coins, 120);
    CHECK_EQ(chooseSave("junk", "", out), 0); CHECK_EQ(out.level, 1); CHECK_EQ(out.coins, 0);
}
TEST("high scores") {
    std::vector<Score> t;
    CHECK_EQ(addScore(t, "A", 500), 1); CHECK_EQ(addScore(t, "B", 700), 1); CHECK_EQ(addScore(t, "C", 500), 3);
    CHECK_EQ(addScore(t, "D", 100), 4); CHECK_EQ(addScore(t, "E", 50), 5); CHECK_EQ(addScore(t, "F", 50), 0); CHECK_EQ(addScore(t, "G", 600), 2);
    CHECK_EQ(t.size(), std::size_t{ 5 }); CHECK_EQ(t[2].name, std::string("A")); CHECK_EQ(t[3].name, std::string("C")); CHECK_EQ(t[4].name, std::string("D"));
}

